excels.excel:

EXPORT WITH SHEET="差旅补贴发放明细表", HEADER=true,
    MAPPING={"a":"姓名","b":"部门","c":"出差地点","d":"出差天数","e":"日补贴标准","f":"交通补贴","g":"补贴合计"},
    FORMAT={"d":"0","e":"#,##0.00","f":"#,##0.00","g":"#,##0.00"},
    FORMULAS={
        G2:'D2*E2+F2',G3:'D3*E3+F3',G4:'D4*E4+F4',
        G5:'D5*E5+F5',G6:'D6*E6+F6',G7:'D7*E7+F7',
        D8:'SUM(D2:D7)',F8:'SUM(F2:F7)',G8:'SUM(G2:G7)'
    },
    STYLE={ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}}
